import type { OrgChat } from "@/lib/org-community";

/**
 * Organization data for every program other than LFX, generated by
 * scripts/programs/collect.mjs from each program's official list and the organizations' own
 * GitHub accounts and websites. The files are committed, so pages never fetch live.
 */

export interface ProgramOrgProject {
  year: number;
  title: string;
  url?: string;
  round?: string;
  product?: string | null;
}

export interface ProgramOrg {
  slug: string;
  name: string;
  tagline: string | null;
  description: string | null;
  website: string | null;
  repoUrl: string | null;
  githubUrl?: string | null;
  sourceCodeUrl?: string | null;
  logo: string | null;
  /** The published logo is light-coloured and must sit on a dark tile. */
  logoOnDark?: boolean;
  tags: string[];
  categories?: string[];
  years: number[];
  rounds?: string[];
  projects?: ProgramOrgProject[];
  links: { label: string; url: string }[];
  chats: OrgChat[];
  chatSource?: string | null;
  sourceUrl: string;
}

export interface ProgramData {
  program: string;
  name: string;
  generatedAt: string;
  years: number[];
  note: string;
  sources: { label: string; url: string }[];
  orgs: ProgramOrg[];
}

const LOADERS: Record<string, () => Promise<{ default: unknown }>> = {
  gsoc: () => import("@/data/programs/gsoc.json"),
  "season-of-docs": () => import("@/data/programs/season-of-docs.json"),
  outreachy: () => import("@/data/programs/outreachy.json"),
  "summer-of-bitcoin": () => import("@/data/programs/summer-of-bitcoin.json"),
  "european-summer-of-code": () => import("@/data/programs/european-summer-of-code.json"),
  ospp: () => import("@/data/programs/ospp.json"),
  c4gt: () => import("@/data/programs/c4gt.json"),
  "mlh-fellowship": () => import("@/data/programs/mlh-fellowship.json"),
  igalia: () => import("@/data/programs/igalia.json"),
  "processing-foundation": () => import("@/data/programs/processing-foundation.json"),
};

export async function programData(slug: string): Promise<ProgramData | null> {
  const load = LOADERS[slug];
  if (!load) return null;
  return (await load()).default as ProgramData;
}

export async function programOrg(slug: string, orgSlug: string) {
  const data = await programData(slug);
  const org = data?.orgs.find((o) => o.slug === decodeURIComponent(orgSlug)) ?? null;
  return data && org ? { data, org } : null;
}

export interface OrgFilter {
  q?: string;
  tech?: string;
  year?: string;
}

export function filterOrgs(orgs: ProgramOrg[], f: OrgFilter) {
  const q = f.q?.trim().toLowerCase();
  const tech = f.tech?.trim().toLowerCase();
  const year = f.year ? Number(f.year) : null;
  return orgs.filter((o) => {
    if (year && !o.years.includes(year)) return false;
    if (tech && !o.tags.some((t) => t.toLowerCase() === tech)) return false;
    if (q) {
      const hay = [o.name, o.tagline, o.description, ...o.tags].join(" ").toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });
}

export function tagFacets(orgs: ProgramOrg[]) {
  const m = new Map<string, { value: string; n: number }>();
  for (const o of orgs)
    for (const t of o.tags) {
      const k = t.toLowerCase();
      const cur = m.get(k) ?? { value: t, n: 0 };
      cur.n++;
      m.set(k, cur);
    }
  return [...m.values()].sort((a, b) => b.n - a.n || a.value.localeCompare(b.value));
}

export function yearRange(years: number[]) {
  if (years.length === 0) return null;
  const s = [...years].sort((a, b) => a - b);
  return s.length === 1 ? String(s[0]) : `${s[0]}–${s[s.length - 1]}`;
}
